(()=>{
 const en=document.documentElement.lang==='en',t=(zh,english)=>en?english:zh,$=id=>document.getElementById(id);
 const panel=document.createElement('section');panel.className='planner';panel.id='live-transit';
 panel.innerHTML=`<p class="eyebrow">CONNECTED JOURNEY / ROUTE ONLY</p><h2>${t('从出发地，衔接到教学楼','From the origin to the classroom')}</h2><p>${t('路线衔接示意，使用已选课程与出行方式生成。此处不请求 TransportAPI，不消耗其查询额度；不表示已核实班次、线路或实际道路路径。','A connection outline from the selected class and travel mode. No TransportAPI requests or quota use here. Services, routes and street paths are not verified.')}</p><label id="railOriginLabel" hidden>${t('确认火车上车站（可选）','Confirm the boarding station (optional)')}<select id="railBoarding"><option value="">${t('尚未确认上车站','Boarding station not confirmed')}</option><option>Birmingham New Street</option><option>Five Ways</option><option>Selly Oak</option></select></label><ol id="connectionSteps" class="connection-steps"></ol><p id="connectionStatus" role="status"></p>`;
 $('map').before(panel);let mode=null,fromBuilding=null,course=null;
 const names={train:t('火车','Train'),bus:t('公交','Bus'),walk:t('步行','Walk'),cycle:t('骑行','Cycle'),taxi:t('打车','Taxi'),combo:t('公交＋火车','Bus + train')};
 function render(){const list=$('connectionSteps');list.replaceChildren();$('railOriginLabel').hidden=!['train','combo'].includes(mode);if(!mode){$('connectionStatus').textContent=t('选择通勤方案或导入课程并建立档案后，自动显示路线衔接。','Choose a commute option, or import classes and create a profile, to see the connection.');return;}
 const origin=$('area').value,destination=$('building').selectedOptions[0]?.textContent||'',building=course?.building===$('building').value&&course?.room?destination+' · '+course.room:destination;
 const steps=fromBuilding?[fromBuilding,t('课间校园步行','Walk between classes'),building]:mode==='train'?[origin,$('railBoarding').value||t('火车上车站待确认','Boarding station pending'),'University Station',building]:mode==='combo'?[origin,t('公交上车站／下车站待确认','Bus boarding / alighting stops pending'),$('railBoarding').value||t('火车换乘站待确认','Rail interchange pending'),'University Station',building]:mode==='bus'?[origin,t('公交上车站待确认','Boarding bus stop pending'),$('campusStart').value==='bus'&&$('campusBus').value.trim()?$('campusBus').value.trim():t('校园周边下车站待确认','Campus alighting stop pending'),building]:mode==='cycle'?[origin,t('骑行路段待核实','Cycle route unverified'),$('campusStart').value==='bike'&&$('campusBus').value.trim()?$('campusBus').value.trim():t('单车停放点待确认','Cycle parking pending'),building]:mode==='taxi'?[origin,t('出租车行程','Taxi leg'),$('campusStart').value==='taxi'&&$('campusBus').value.trim()?$('campusBus').value.trim():t('下车点待确认','Drop-off point pending'),building]:[origin,t('步行路径由外部地图确认','Confirm the walking path in the external map'),building];
 steps.forEach((text,i)=>{const li=document.createElement('li'),n=document.createElement('span'),p=document.createElement('b');n.textContent=String(i+1).padStart(2,'0');p.textContent=text;li.append(n,p);list.append(li);});$('connectionStatus').textContent=(fromBuilding?t('校内转场','Campus transfer'):names[mode])+' · '+t('仅示意衔接，不查询实时信息。校园导航沿用相应到达点。','Connection outline only; no live lookup. Campus navigation uses the corresponding arrival point.');
 }
 $('railBoarding').onchange=render;window.addEventListener('greengo:mode-selected',e=>{mode=e.detail.mode;fromBuilding=e.detail.fromBuilding||null;render();});window.addEventListener('greengo:class-selected',e=>{course=e.detail;render();});['area','building','campusStart'].forEach(id=>$(id)?.addEventListener('change',render));$('campusBus')?.addEventListener('input',render);
 // Campus controls are created by the following script; bind when the page is ready.
 document.addEventListener('DOMContentLoaded',()=>{['campusStart','campusBus'].forEach(id=>$(id)?.addEventListener(id==='campusBus'?'input':'change',render));});
 const css=document.createElement('style');css.textContent='.connection-steps{list-style:none;padding:0;display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:12px;margin:20px 0}.connection-steps li{background:#fffdf7;border:1px solid #d4dfce;border-top:3px solid #ffcc4a;border-radius:8px;padding:17px 14px;min-width:0}.connection-steps span{display:block;color:#7b907c;font-size:10px;margin-bottom:12px}.connection-steps b{font-size:12px;line-height:1.6;display:block}#connectionStatus{font-size:12px;color:#6c7f70}#railOriginLabel{max-width:400px}@media(max-width:500px){.connection-steps{grid-template-columns:1fr}.connection-steps li{display:flex;gap:15px;align-items:center;padding:13px}.connection-steps span{margin:0}}';document.head.append(css);render();
})();
